package com.nextaicommerce.platform.shipping;
import java.util.*;import org.junit.jupiter.api.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import tools.jackson.databind.ObjectMapper;
class AmazonFedExSandboxShippingTest {
 final UUID tenant=UUID.randomUUID(),store=UUID.randomUUID(),quote=UUID.randomUUID(),carrierId=UUID.randomUUID();final String order="114-1234567-1234567";
 final CarrierOrderContext orders=mock(CarrierOrderContext.class);final OrderRecipientService recipients=mock(OrderRecipientService.class);final FedExSandboxRates carrier=mock(FedExSandboxRates.class);final CarrierConnectionRepository connections=mock(CarrierConnectionRepository.class);final FedExShipmentRepository shipments=mock(FedExShipmentRepository.class);final ShippingLabelCrypto crypto=mock(ShippingLabelCrypto.class);final CarrierLabelComposer composer=mock(CarrierLabelComposer.class);final ObjectMapper json=new ObjectMapper();AmazonFedExSandboxShipping service;
 @BeforeEach void setup(){service=new AmazonFedExSandboxShipping(true,orders,recipients,carrier,connections,shipments,crypto,composer,json);when(carrier.account()).thenReturn("740561073");when(crypto.configured()).thenReturn(true);when(orders.rateOnlyContext(tenant,store,order)).thenReturn(context("Unshipped","MFN"));}
 BuyShippingService.Context context(String status,String channel){return new BuyShippingService.Context(null,new BuyShippingRepository.OrderInfo(order,status,channel,null,null,null,null,null),List.of(new BuyShippingRepository.OrderItem("line","0001",null,"Product",2,0)),List.of(),List.of(),null,List.of(),Map.of());}
 FedExShipmentRepository.Shipment row(String state){return new FedExShipmentRepository.Shipment(quote,carrierId,1,order,"SANDBOX",state,json.createArrayNode(),json.createArrayNode(),null,null);}
 @Test void disabledAndNonAmazonIdsCannotReachArchiveOrRecipients(){var disabled=new AmazonFedExSandboxShipping(false,orders,recipients,carrier,connections,shipments,crypto,composer,json);assertThatThrownBy(()->disabled.history(tenant,store,order)).isInstanceOf(IllegalStateException.class);assertThatThrownBy(()->service.history(tenant,store,UUID.randomUUID().toString())).isInstanceOf(IllegalArgumentException.class);when(orders.shopify(tenant,store)).thenReturn(true);assertThatThrownBy(()->service.history(tenant,store,order)).isInstanceOf(IllegalArgumentException.class);verifyNoInteractions(recipients,shipments,connections);}
 @Test void missingEncryptionStopsBeforeCarrierOrRecipientRead(){when(crypto.configured()).thenReturn(false);assertThatThrownBy(()->service.quote(tenant,store,order,null,"actor")).hasMessageContaining("encryption");verifyNoInteractions(recipients,shipments,connections);verify(carrier,never()).quote(any(),any(),any(),any(),any());}
 @Test void incompleteOrMissingRecipientNeverCallsFedEx(){for(String state:List.of("LOCAL_CONNECTION_REQUIRED","ACCESS_DENIED","INCOMPLETE","NOT_AVAILABLE")){when(recipients.localShipping(tenant,store,order)).thenReturn(new OrderRecipientService.View(state,null));assertThatThrownBy(()->service.quote(tenant,store,order,null,"actor")).isInstanceOf(IllegalStateException.class);}verify(carrier,never()).quote(any(),any(),any(),any(),any());verify(shipments,never()).quote(any(),any(),any(),any(),any(),any(),any(),any());}
 @Test void fbaShippedAndAlreadyCommittedOrdersAreRejected(){for(var c:List.of(context("Shipped","MFN"),context("Unshipped","AFN"))){when(orders.rateOnlyContext(tenant,store,order)).thenReturn(c);assertThatThrownBy(()->service.recipient(tenant,store,order)).isInstanceOf(IllegalStateException.class);}verifyNoInteractions(recipients,shipments);}
 @Test void duplicatePurchaseReusesArchiveAndUnknownOutcomeNeverRetries(){var saved=row("PURCHASED");when(shipments.protectedShipment(tenant,store,order)).thenReturn(saved);assertThat(service.purchase(tenant,store,order,UUID.randomUUID(),"FEDEX_GROUND")).isSameAs(saved);when(shipments.protectedShipment(tenant,store,order)).thenReturn(row("UNKNOWN"));assertThatThrownBy(()->service.purchase(tenant,store,order,quote,"FEDEX_GROUND")).hasMessageContaining("review");verify(carrier,never()).ship(any(),any(),any());verify(shipments,never()).claim(any(),any(),any(),any(),any(),anyLong());verifyNoInteractions(connections,recipients);}
 @Test void anotherQuoteAndLegacyOrMissingPackingAreRejectedBeforeClaim(){when(shipments.list(tenant,store,order)).thenReturn(List.of(row("RATED")));assertThatThrownBy(()->service.purchase(tenant,store,order,UUID.randomUUID(),"FEDEX_GROUND")).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->service.purchase(tenant,store,order,quote,"FEDEX_GROUND")).hasMessageContaining("Packing details changed");verify(shipments,never()).claim(any(),any(),any(),any(),any(),anyLong());verify(carrier,never()).ship(any(),any(),any());}
}
